    row_modes = [_mode(row) for row in grid]
    col_modes = [_mode([grid[r][c] for r in range(h)]) for c in range(w)]
    line_modes = [v for v in row_modes + col_modes if v != background]
    if not line_modes:
        return []
    separator = Counter(line_modes).most_common(1)[0][0]

